    ('7b0e4de1-3212-46bc-b5fd-40ac1793faa1'::uuid, 'site_type', NULL, 'Archaeological site', 'fields-wd3-2026-10-02b-s006:7b0e4de1-3212-46bc-b5fd-40ac1793faa1:site_type', 'fields-wd3-2026-10-02b-s006 (wd3-replace): None -> ''Archaeological site''', '[{"source": "https://en.wikipedia.org/wiki/Adullam_Grove_Nature_Reserve", "url": "https://en.wikipedia.org/wiki/Adullam_Grove_Nature_Reserve", "quote": "The park is full with archaeological sites, including a number of ruins of rural villages", "outcome": "found"}, {"source": "WD3 decision (counted, round 0, wd3-r0-b0182)", "decision": "replace", "status": "MISSING", "reasoning": "Wikipedia describes the Adullam Grove reserve as full of archaeological sites (ruined villages, burial caves, columbarium, burial pyramid, churches); it is a mixed multi-site reserve, so no specific type such as Necropolis or Settlement fits and the generic Archaeological site is the right one.", "value_page": null, "model": "anthropic/claude-sonnet-5-5 (Claude Code agent)"}]'::jsonb),
    ('7b39da13-0cb0-43cd-a3a8-a22b9c990ca1'::uuid, 'site_type', NULL, 'Bridge', 'fields-wd3-2026-10-02b-s006:7b39da13-0cb0-43cd-a3a8-a22b9c990ca1:site_type', 'fields-wd3-2026-10-02b-s006 (wd3-replace): None -> ''Bridge''', '[{"source": "https://www.consorciomerida.org/conjunto/monumentos/alcantarilla", "url": "https://www.consorciomerida.org/conjunto/monumentos/alcantarilla", "quote": "Se construyó en el siglo I a.C para salvar un pequeño arroyo. El puente, de un solo arco, está realizado en hormigón romano y cubierto con sillares almohadillados de los que apenas se conservan restos.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Archaeological_Ensemble_of_M%C3%A9rida", "url": "https://en.wikipedia.org/wiki/Archaeological_Ensemble_of_M%C3%A9rida", "quote": "Alcantarilla Bridge", "outcome": "found"}, {"source": "WD3 decision (counted, round 0, wd3-r0-b0289)", "decision": "replace", "status": "MISSING", "reasoning": "The consortium of the monumental ensemble of Mérida describes the monument as a single-arch bridge built in Roman concrete in the 1st century BC, and the English article on the UNESCO Archaeological Ensemble of Mérida lists this very component of the ensemble in Mérida under the name \"Alcantarilla Bridge\"; a bridge is the canonical type Bridge.", "value_page": null, "model": "minimax/MiniMax-M3.1-Flash-Preview (MiniMax Code agent)"}]'::jsonb),
